use std::io::{self, BufRead, BufReader, Write};
use std::net::TcpStream;

const JSON_CONTENT_TYPE: &str = "application/json; charset=utf-8";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HttpResponse {
    status_code: u16,
    reason_phrase: &'static str,
    body: &'static str,
    allow_get: bool,
}

impl HttpResponse {
    pub fn status_code(self) -> u16 {
        self.status_code
    }

    pub fn content_type(self) -> &'static str {
        JSON_CONTENT_TYPE
    }

    pub fn body(self) -> &'static str {
        self.body
    }

    pub fn allow(self) -> Option<&'static str> {
        self.allow_get.then_some("GET")
    }

    pub fn write_to<W: Write>(self, writer: &mut W) -> io::Result<()> {
        write!(
            writer,
            "HTTP/1.1 {} {}\r\nContent-Type: {}\r\nContent-Length: {}\r\n",
            self.status_code,
            self.reason_phrase,
            JSON_CONTENT_TYPE,
            self.body.len()
        )?;

        if self.allow_get {
            writer.write_all(b"Allow: GET\r\n")?;
        }

        writer.write_all(b"Connection: close\r\n\r\n")?;
        writer.write_all(self.body.as_bytes())?;
        writer.flush()
    }
}

pub fn response_for(method: &str, target: &str) -> HttpResponse {
    let path = target.split(['?', '#']).next().unwrap_or(target);

    if path == "/ping" {
        if method == "GET" {
            return HttpResponse {
                status_code: 200,
                reason_phrase: "OK",
                body: r#"{"message":"pong"}"#,
                allow_get: false,
            };
        }

        return HttpResponse {
            status_code: 405,
            reason_phrase: "Method Not Allowed",
            body: r#"{"error":"Method Not Allowed"}"#,
            allow_get: true,
        };
    }

    HttpResponse {
        status_code: 404,
        reason_phrase: "Not Found",
        body: r#"{"error":"Not Found"}"#,
        allow_get: false,
    }
}

pub fn handle_connection(mut stream: TcpStream) -> io::Result<()> {
    let mut request_line = String::new();
    {
        let mut reader = BufReader::new(&mut stream);
        if reader.read_line(&mut request_line)? == 0 {
            return Ok(());
        }
    }

    let mut request_parts = request_line.split_whitespace();
    let method = request_parts.next().unwrap_or("");
    let target = request_parts.next().unwrap_or("/");

    response_for(method, target).write_to(&mut stream)
}

#[cfg(test)]
mod tests {
    use super::{response_for, HttpResponse};

    fn assert_json_response(response: HttpResponse, status_code: u16, body: &'static str) {
        assert_eq!(response.status_code(), status_code);
        assert_eq!(response.content_type(), "application/json; charset=utf-8");
        assert_eq!(response.body(), body);
    }

    #[test]
    fn get_ping_returns_pong_json() {
        let response = response_for("GET", "/ping?from=test");

        assert_json_response(response, 200, r#"{"message":"pong"}"#);
        assert_eq!(response.allow(), None);
    }

    #[test]
    fn non_get_ping_returns_method_not_allowed_with_allow_header() {
        let response = response_for("POST", "/ping");

        assert_json_response(response, 405, r#"{"error":"Method Not Allowed"}"#);
        assert_eq!(response.allow(), Some("GET"));
    }

    #[test]
    fn unknown_route_returns_not_found_without_allow_header() {
        let response = response_for("GET", "/unknown");

        assert_json_response(response, 404, r#"{"error":"Not Found"}"#);
        assert_eq!(response.allow(), None);
    }

    #[test]
    fn response_writes_http_json_headers_and_body() {
        let response = response_for("POST", "/ping");
        let mut wire_response = Vec::new();

        response.write_to(&mut wire_response).unwrap();

        assert_eq!(
            String::from_utf8(wire_response).unwrap(),
            concat!(
                "HTTP/1.1 405 Method Not Allowed\r\n",
                "Content-Type: application/json; charset=utf-8\r\n",
                "Content-Length: 30\r\n",
                "Allow: GET\r\n",
                "Connection: close\r\n",
                "\r\n",
                "{\"error\":\"Method Not Allowed\"}"
            )
        );
    }
}

--- rust main ---
use std::env;
use std::io;
use std::net::TcpListener;
use std::thread;

use ping_pong_api::handle_connection;

fn main() -> io::Result<()> {
    let host = env::var("HOST").unwrap_or_else(|_| "0.0.0.0".to_owned());
    let port = parse_port(&env::var("PORT").unwrap_or_else(|_| "3000".to_owned()))?;
    let listener = TcpListener::bind((host.as_str(), port))?;

    println!("Ping-pong API listening on http://{host}:{port}");

    for incoming in listener.incoming() {
        match incoming {
            Ok(stream) => {
                thread::spawn(move || {
                    if let Err(error) = handle_connection(stream) {
                        eprintln!("connection error: {error}");
                    }
                });
            }
            Err(error) => eprintln!("accept error: {error}"),
        }
    }

    Ok(())
}

fn parse_port(value: &str) -> io::Result<u16> {
    value
        .parse::<u16>()
        .ok()
        .filter(|port| *port > 0)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "PORT must be an integer between 1 and 65535",
            )
        })
}

#[cfg(test)]
mod tests {
    use super::parse_port;

    #[test]
    fn parse_port_accepts_valid_port_numbers() {
        assert_eq!(parse_port("1").unwrap(), 1);
        assert_eq!(parse_port("3000").unwrap(), 3000);
        assert_eq!(parse_port("65535").unwrap(), 65535);
    }

    #[test]
    fn parse_port_rejects_zero() {
        assert!(parse_port("0").is_err());
    }

    #[test]
    fn parse_port_rejects_non_numeric_values() {
        assert!(parse_port("not-a-port").is_err());
        assert!(parse_port("").is_err());
    }

    #[test]
    fn parse_port_rejects_values_outside_u16_range() {
        assert!(parse_port("65536").is_err());
    }
}

--- README ---
# Ping-pong API

Small HTTP API with TypeScript, Go, Rust, and Python implementations.

## TypeScript

Run locally:

```bash
npm install
npm run dev
```

The server listens on port `3000` by default. Set `PORT` or `HOST` to change
the binding.

## Configuration

Keep the API key in your local environment; do not commit the real value:

```bash
export API_KEY="replace-with-your-api-key"
```

## Endpoint

```bash
curl http://localhost:3000/ping
# {"message":"pong","count":1}
```

Only `GET /ping` is supported. Unknown routes return `404`, and other methods
on `/ping` return `405`.

Each successful ping is logged with the current pong counter.

## Go

Run locally from the Go implementation directory:

```bash
cd go
go run .
```

Run its tests with `go test ./...`.

## Rust

Run locally from the Rust implementation directory:

```bash
cd rust
cargo run
```

Run its tests with `cargo test`.

## Zig

Run locally with Zig 0.12 or newer:

```bash
cd zig
zig run main.zig
```

Run its tests with `zig test main.zig`.

## Python

Run locally with Python's standard library:

```bash
python -m python.server
```

Run the Python tests:

```bash
python -m unittest discover -s python -p 'test_*.py'
```

## Verify

```bash
npm test
```

## Implementations

The equivalent implementations live in [`go/`](go/), [`rust/`](rust/),
[`zig/`](zig/), and [`python/`](python/). Each directory is self-contained and
includes its own run and test instructions.

All implementations expose the same contract:

- `GET /ping` returns `200` with `{"message":"pong","count":n}` and
  increments the in-memory pong counter.
- Other methods on `/ping` return `405` with `Allow: GET`.
- Unknown routes return `404` with `{"error":"Not Found"}`.

