package main

import (
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
)

func TestPingPongHandler(t *testing.T) {
	tests := []struct {
		name        string
		method      string
		target      string
		wantStatus  int
		wantBody    string
		wantAllow   string
		wantContent string
	}{
		{
			name:        "GET /ping",
			method:      http.MethodGet,
			target:      "/ping",
			wantStatus:  http.StatusOK,
			wantBody:    `{"message":"pong"}`,
			wantContent: jsonContentType,
		},
		{
			name:        "GET /ping with query string",
			method:      http.MethodGet,
			target:      "/ping?source=test",
			wantStatus:  http.StatusOK,
			wantBody:    `{"message":"pong"}`,
			wantContent: jsonContentType,
		},
		{
			name:        "POST /ping",
			method:      http.MethodPost,
			target:      "/ping",
			wantStatus:  http.StatusMethodNotAllowed,
			wantBody:    `{"error":"Method Not Allowed"}`,
			wantAllow:   http.MethodGet,
			wantContent: jsonContentType,
		},
		{
			name:        "unknown route",
			method:      http.MethodGet,
			target:      "/unknown",
			wantStatus:  http.StatusNotFound,
			wantBody:    `{"error":"Not Found"}`,
			wantContent: jsonContentType,
		},
		{
			name:        "encoded ping route",
			method:      http.MethodGet,
			target:      "/%70ing",
			wantStatus:  http.StatusNotFound,
			wantBody:    `{"error":"Not Found"}`,
			wantContent: jsonContentType,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			request := httptest.NewRequest(test.method, test.target, nil)
			response := httptest.NewRecorder()

			newHandler().ServeHTTP(response, request)

			result := response.Result()
			defer result.Body.Close()

			if result.StatusCode != test.wantStatus {
				t.Fatalf("status = %d, want %d", result.StatusCode, test.wantStatus)
			}

			body, err := io.ReadAll(result.Body)
			if err != nil {
				t.Fatalf("read response body: %v", err)
			}
			if string(body) != test.wantBody {
				t.Errorf("body = %q, want %q", body, test.wantBody)
			}

			if contentType := result.Header.Get("Content-Type"); contentType != test.wantContent {
				t.Errorf("Content-Type = %q, want %q", contentType, test.wantContent)
			}

			if allow := result.Header.Get("Allow"); allow != test.wantAllow {
				t.Errorf("Allow = %q, want %q", allow, test.wantAllow)
			}
		})
	}
}

func TestConfiguredPort(t *testing.T) {
	tests := []struct {
		name  string
		value *string
		want  int
		err   bool
	}{
		{name: "unset uses default", value: nil, want: defaultPort},
		{name: "valid port", value: stringPtr("8080"), want: 8080},
		{name: "zero is invalid", value: stringPtr("0"), err: true},
		{name: "port above range is invalid", value: stringPtr("65536"), err: true},
		{name: "non-numeric port is invalid", value: stringPtr("not-a-port"), err: true},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			if test.value == nil {
				t.Setenv("PORT", "")
				if err := os.Unsetenv("PORT"); err != nil {
					t.Fatalf("unset PORT: %v", err)
				}
			} else {
				t.Setenv("PORT", *test.value)
			}

			got, err := configuredPort()
			if (err != nil) != test.err {
				t.Fatalf("configuredPort() error = %v, want error: %t", err, test.err)
			}
			if !test.err && got != test.want {
				t.Errorf("configuredPort() = %d, want %d", got, test.want)
			}
		})
	}
}

func stringPtr(value string) *string {
	return &value
}
package main

import (
	"errors"
	"log"
	"net"
	"net/http"
	"os"
	"strconv"
)

const defaultPort = 3000

func main() {
	host := os.Getenv("HOST")
	if host == "" {
		host = "0.0.0.0"
	}

	port, err := configuredPort()
	if err != nil {
		log.Fatal(err)
	}

	address := net.JoinHostPort(host, strconv.Itoa(port))
	log.Printf("Ping-pong API listening on http://%s", address)
	log.Fatal(http.ListenAndServe(address, newHandler()))
}

func configuredPort() (int, error) {
	value, configured := os.LookupEnv("PORT")
	if !configured {
		return defaultPort, nil
	}

	port, err := strconv.Atoi(value)
	if err != nil || port < 1 || port > 65_535 {
		return 0, errors.New("PORT must be an integer between 1 and 65535")
	}

	return port, nil
}
use std::io::{self, BufRead, BufReader, Write};
use std::net::TcpStream;

const JSON_CONTENT_TYPE: &str = "application/json; charset=utf-8";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HttpResponse {
    status_code: u16,
    reason_phrase: &'static str,
    body: &'static str,
    allow_get: bool,
}

impl HttpResponse {
    pub fn status_code(self) -> u16 {
        self.status_code
    }

    pub fn content_type(self) -> &'static str {
        JSON_CONTENT_TYPE
    }

    pub fn body(self) -> &'static str {
        self.body
    }

    pub fn allow(self) -> Option<&'static str> {
        self.allow_get.then_some("GET")
    }

    pub fn write_to<W: Write>(self, writer: &mut W) -> io::Result<()> {
        write_response(&self, true, writer)
    }
}

pub fn response_for(method: &str, target: &str) -> HttpResponse {
    let path = target.split(['?', '#']).next().unwrap_or(target);

    if path == "/ping" {
        if method == "GET" {
            return HttpResponse {
                status_code: 200,
                reason_phrase: "OK",
                body: r#"{"message":"pong"}"#,
                allow_get: false,
            };
        }

        return HttpResponse {
            status_code: 405,
            reason_phrase: "Method Not Allowed",
            body: r#"{"error":"Method Not Allowed"}"#,
            allow_get: true,
        };
    }

    HttpResponse {
        status_code: 404,
        reason_phrase: "Not Found",
        body: r#"{"error":"Not Found"}"#,
        allow_get: false,
    }
}

pub fn handle_connection(mut stream: TcpStream) -> io::Result<()> {
    let mut request_line = String::new();
    {
        let mut reader = BufReader::new(&mut stream);
        if reader.read_line(&mut request_line)? == 0 {
            return Ok(());
        }
    }

    let mut request_parts = request_line.split_whitespace();
    let method = request_parts.next().unwrap_or("");
    let target = request_parts.next().unwrap_or("/");

    let response = response_for(method, target);
    write_response(&response, method != "HEAD", &mut stream)
}

fn write_response<W: Write>(
    response: &HttpResponse,
    include_body: bool,
    writer: &mut W,
) -> io::Result<()> {
    write!(
        writer,
        "HTTP/1.1 {} {}\r\nContent-Type: {}\r\nContent-Length: {}\r\n",
        response.status_code,
        response.reason_phrase,
        JSON_CONTENT_TYPE,
        response.body.len()
    )?;

    if response.allow_get {
        writer.write_all(b"Allow: GET\r\n")?;
    }

    writer.write_all(b"Connection: close\r\n\r\n")?;
    if include_body {
        writer.write_all(response.body.as_bytes())?;
    }
    writer.flush()
}

#[cfg(test)]
mod tests {
    use super::{response_for, HttpResponse};

    fn assert_json_response(response: HttpResponse, status_code: u16, body: &'static str) {
        assert_eq!(response.status_code(), status_code);
        assert_eq!(response.content_type(), "application/json; charset=utf-8");
        assert_eq!(response.body(), body);
    }

    #[test]
    fn get_ping_returns_pong_json() {
        let response = response_for("GET", "/ping?from=test");

        assert_json_response(response, 200, r#"{"message":"pong"}"#);
        assert_eq!(response.allow(), None);
    }

    #[test]
    fn non_get_ping_returns_method_not_allowed_with_allow_header() {
        let response = response_for("POST", "/ping");

        assert_json_response(response, 405, r#"{"error":"Method Not Allowed"}"#);
        assert_eq!(response.allow(), Some("GET"));
    }

    #[test]
    fn unknown_route_returns_not_found_without_allow_header() {
        let response = response_for("GET", "/unknown");

        assert_json_response(response, 404, r#"{"error":"Not Found"}"#);
        assert_eq!(response.allow(), None);
    }

    #[test]
    fn response_writes_http_json_headers_and_body() {
        let response = response_for("POST", "/ping");
        let mut wire_response = Vec::new();

        response.write_to(&mut wire_response).unwrap();

        assert_eq!(
            String::from_utf8(wire_response).unwrap(),
            concat!(
                "HTTP/1.1 405 Method Not Allowed\r\n",
                "Content-Type: application/json; charset=utf-8\r\n",
                "Content-Length: 30\r\n",
                "Allow: GET\r\n",
                "Connection: close\r\n",
                "\r\n",
                "{\"error\":\"Method Not Allowed\"}"
            )
        );
    }

    #[test]
    fn head_response_writes_headers_without_body() {
        let response = response_for("HEAD", "/ping");
        let mut wire_response = Vec::new();

        super::write_response(&response, false, &mut wire_response).unwrap();

        assert_eq!(
            String::from_utf8(wire_response).unwrap(),
            concat!(
                "HTTP/1.1 405 Method Not Allowed\r\n",
                "Content-Type: application/json; charset=utf-8\r\n",
